package cn.balltv.portal;
import android.content.*;import android.graphics.*;import android.view.*;import android.widget.*;import android.os.*;import java.util.*;import java.util.concurrent.*;import com.google.android.exoplayer2.*;import com.google.android.exoplayer2.ui.*;import com.google.android.exoplayer2.upstream.*;
/** One muted preview, released whenever the home screen leaves the foreground. */
final class LivePreview extends FrameLayout {
 final MainActivity owner;final PlayerView video;final TextView status;final ExecutorService io=Executors.newSingleThreadExecutor();ExoPlayer player;String key="";volatile int token;boolean enabled=true;Events.Group selected;
 LivePreview(MainActivity a){super(a);owner=a;setBackgroundColor(0xff05090f);video=new PlayerView(a);video.setUseController(false);video.setFocusable(false);video.setClickable(false);addView(video,new LayoutParams(-1,-1));status=Ui.text(a,"选择赛事，静音预览",13,Color.WHITE);status.setPadding(18,10,18,10);status.setBackgroundColor(0xb008101c);LayoutParams p=new LayoutParams(-1,-2,Gravity.BOTTOM);addView(status,p);}
 void select(Events.Group g){selected=g;if(!enabled||g.id.equals(key))return;stop();key=g.id;final int request=token;status.setText("正在连接预览 · 静音");ArrayList<Feeds.Match> choices=new ArrayList<Feeds.Match>(g.members);Collections.sort(choices,(a,b)->Integer.compare(rank(a.source),rank(b.source)));io.execute(()->{int attempts=0;for(Feeds.Match m:choices){if(request!=token)return;try{for(Feeds.Line l:Feeds.lines(m)){if(request!=token)return;if(attempts++>7)break;try{String url=Feeds.resolve(m,l);owner.runOnUiThread(()->{if(request==token&&enabled)play(url,l,m,request);});return;}catch(Exception ignored){}}}catch(Exception ignored){}}owner.runOnUiThread(()->{if(request==token)status.setText("预览暂不可用 · 确定进入选择其他线路");});});}
 static int rank(String s){return s.equals(MoreSources.S74)?0:s.equals(MoreSources.S88)?1:s.equals(MoreSources.RAIN)?2:3;}
 void play(String url,Feeds.Line line,Feeds.Match match,int request){DefaultHttpDataSource.Factory http=new DefaultHttpDataSource.Factory().setUserAgent(Feeds.UA).setConnectTimeoutMs(5000).setReadTimeoutMs(5000).setAllowCrossProtocolRedirects(true).setDefaultRequestProperties(Collections.singletonMap("Referer",line.referer.isEmpty()?Feeds.base(match.source)+"/":line.referer));player=new ExoPlayer.Builder(owner).setMediaSourceFactory(new com.google.android.exoplayer2.source.DefaultMediaSourceFactory(new DefaultDataSource.Factory(owner,http))).setLoadControl(new DefaultLoadControl.Builder().setBufferDurationsMs(3000,6000,750,1000).build()).build();video.setPlayer(player);player.setVolume(0);player.addListener(new Player.Listener(){public void onPlaybackStateChanged(int state){if(request==token&&state==Player.STATE_READY)status.setText("LIVE  /  静音预览 · "+match.source);}public void onPlayerError(PlaybackException e){if(request==token){status.setText("预览不可用 · 确定进入换线");if(player!=null){video.setPlayer(null);player.release();player=null;}}}});MediaItem.Builder item=new MediaItem.Builder().setUri(url);if(StreamResolver.direct(url)&&url.contains(".m3u8"))item.setMimeType("application/x-mpegURL");player.setMediaItem(item.build());player.prepare();player.play();}
 void stop(){token++;key="";if(player!=null){video.setPlayer(null);player.release();player=null;}}
 void dispose(){stop();io.shutdownNow();}
}
